 (user_id, status)"},{"name":"adult_access_pkey","ready":true,"valid":true,"definition":"CREATE UNIQUE INDEX adult_access_pkey ON activities_private.adult_access USING btree (user_id)"},{"name":"blocks_pkey","ready":true,"valid":true,"definition":"CREATE UNIQUE INDEX blocks_pkey ON activities_private.blocks USING btree (user_id, blocked_id)"},{"name":"locations_pkey","ready":true,"valid":true,"definition":"CREATE UNIQUE INDEX locations_pkey ON activities_private.locations USING btree (activity_id)"},{"name":"members_pkey","ready":true,"valid":true,"definition":"CREATE UNIQUE INDEX members_pkey ON activities_private.members USING btree (activity_id, user_id)"},{"name":"notices_pkey","ready":true,"valid":true,"definition":"CREATE UNIQUE INDEX notices_pkey ON activities_private.notices USING btree (id)"},{"name":"notices_user_id_activity_id_kind_version_key","ready":true,"valid":true,"definition":"CREATE UNIQUE INDEX notices_user_id_activity_id_kind_version_key ON activities_private.notices USING btree (user_id, activity_id, kind, version)"},{"name":"settings_pkey","ready":true,"valid":true,"definition":"CREATE UNIQUE INDEX settings_pkey ON activities_private.settings USING btree (id)"}],"policies":[],"triggers":[],"functions":[{"acl":"{postgres=X/postgres}","args":"","name":"allowed","owner":"postgres","schema":"activities_private","definition":"CREATE OR REPLACE FUNCTION activities_private.allowed()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\n select auth.uid() is not null and public.myevent_account_active() and exists(select 1 from activities_private.settings where enabled) and exists(select 1 from activities_private.adult_access where user_id=auth.uid() and revoked_at is null)\n$function$\n"},{"acl":"{postgres=X/postgres}","args":"a uuid, b uuid","name":"blocked","owner":"postgres","schema":"activities_private","definition":"CREATE OR REPLACE FUNCTION activities_private.blocked(a uuid, b uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\n select exists(select 1 from activities_private.blocks where (user_id=a and blocked_id=b) or (user_id=b and blocked_id=a))\n$function$\n"},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","args":"","name":"capabilities","owner":"postgres","schema":"activities_private","definition":"CREATE OR REPLACE FUNCTION activities_private.capabilities()\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\n select jsonb_build_object('enabled',coalesce((select enabled from activities_private.settings),false),'adult_access',auth.uid() is not null and public.myevent_account_active() and exists(select 1 from activities_private.adult_access where user_id=auth.uid() and revoked_at is null),'version',1)\n$function$\n"},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","args":"p_id uuid","name":"detail","owner":"postgres","schema":"activities_private","definition":"CREATE OR REPLACE FUNCTION activities_private.detail(p_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare a activities_private.activities%rowtype; me uuid:=auth.uid(); accepted boolean; owner boolean; result jsonb;\nbegin\n if not activities_private.visible(p_id) then return null; end if;\n select * into a from activities_private.activities where id=p_id;\n owner:=a.organizer_id=me;\n accepted:=owner or exists(select 1 from activities_private.members where activity_id=p_id and user_id=me and status='accepted');\n select to_jsonb(a)-'created_at'-'updated_at' || jsonb_build_object(\n  'is_owner',owner,'membership',(select status from activities_private.members where activity_id=p_id and user_id=me),\n  'participants_count',(select count(*) from activities_private.members where activity_id=p_id and status='accepted'),\n  'remaining',greatest(0,a.capacity-(select count(*) from activities_private.members where activity_id=p_id and status='accepted')),\n  'address',case when accepted then l.address else null end,\n  'position',case when l.latitude is null then null else jsonb_build_object('lat',round(l.latitude::numeric,2),'lon',round(l.longitude::numeric,2)) end,\n  'members',case when accepted then coalesce((select jsonb_agg(jsonb_build_object('user_id',m.user_id,'status',m.status,'display_name',coalesce(p.display_name,'Participant'))) from activities_private.members m left join public.profiles p on p.id=m.user_id where m.activity_id=p_id and (m.status='accepted' or (owner and m.status='pending')) and not activities_private.blocked(me,m.user_id)),'[]'::jsonb) else '[]'::jsonb end)\n into result from activities_private.locations l where l.activity_id=p_id;\n return result;\nend $function$\n"},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","args":"","name":"list","owner":"postgres","schema":"activities_private","definition":"CREATE OR REPLACE FUNCTION activities_private.list()\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\n select coalesce(jsonb_agg(x.detail order by x.starts_at),'[]'::jsonb) from (\n select a.starts_at,activities_private.detail(a.id)-'members'-'address'-'description'-'conditions' as detail\n from activities_private.activities a where activities_private.visible(a.id) and (a.starts_at>now() or a.organizer_id=auth.uid() or exists(select 1 from activities_private.members m where m.activity_id=a.id and m.user_id=auth.uid() and m.status in ('accepted','pending'))) order by a.starts_at limit 300) x\n$function$\n"},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","args":"p_id uuid, p_action text, p_user uuid","name":"participate","owner":"postgres","schema":"activities_private","definition":"CREATE OR REPLACE FUNCTION activities_private.participate(p_id uuid, p_action text, p_user uuid DEFAULT NULL::uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare me uuid:=auth.uid();a activities_private.activities%rowtype;target uuid:=coalesce(p_user,auth.uid());previous text;n integer;\nbegin\n if not activities_private.allowed() then raise exception 'Accès adulte non autorisé'; end if;\n -- Every seat mutation and capacity edit uses this exact activity row lock.\n select * into a from activities_private.activities where id=p_id for update;\n if not found then raise exception 'Activité introuvable'; end if;\n if p_action='leave' then\n  if target<>me or a.organizer_id=me then raise exception 'Annulez votre activité en tant qu’organisateur'; end if;\n  update activities_private.members set status='left',updated_at=clock_timestamp() where activity_id=p_id and user_id=me and status in ('accepted','pending');\n  if found then insert into activities_private.notices(user_id,activity_id,kind) values(a.organizer_id,p_id,'left') on conflict do nothing; end if;\n  return;\n end if;\n if not activities_private.visible(p_id) then raise exception 'Activité inaccessible'; end if;\n if p_action in ('cancel','delete') then\n  if a.organizer_id<>me then raise exception 'Réservé à l’organisateur'; end if;\n  if a.status='deleted' or (a.status='cancelled' and p_action='cancel') then return; end if;\n  update activities_private.activities set status=case when p_action='cancel' then 'cancelled' else 'deleted' end,updated_at=clock_timestamp() where id=p_id;\n  update activities_private.locations set address='',latitude=null,longitude=null where activity_id=p_id;\n  insert into activities_private.notices(user_id,activity_id,kind) select user_id,p_id,p_action from activities_private.members where activity_id=p_id and user_id<>me and status in ('accepted','pending') on conflict do nothing;\n  return;\n end if;\n if a.status<>'open' or a.starts_at<=now() then raise exception 'Inscriptions fermées'; end if;\n select status into previous from activities_private.members where activity_id=p_id and user_id=target;\n if p_action='join' then\n  if target<>me then raise exception 'Inscription pour soi uniquement'; end if;\n  if previous in ('accepted','pending') then return; end if;\n  if previous='declined' then raise exception 'Demande refusée par l’organisateur'; end if;\n  if (select count(*) from activities_private.members where user_id=me and updated_at>now()-interval '1 hour')>=20 then raise exception 'Trop de demandes récentes'; end if;\n elsif p_action in ('accept','decline') then\n  if a.organizer_id<>me or target=me or previous is distinct from 'pending' then raise exception 'Demande non modifiable'; end if;\n  if activities_private.blocked(me,target) then raise exception 'Utilisateur bloqué'; end if;\n  if not exists(select 1 from activities_private.adult_access where user_id=target and revoked_at is null) then raise exception 'Accès adulte révoqué'; end if;\n else raise exception 'Action inconnue'; end if;\n if p_action='accept' or (p_action='join' and a.join_mode='direct') then\n  select count(*) into n from activities_private.members where activity_id=p_id and status='accepted';\n  if n>=a.capacity then raise exception 'Activité complète'; end if;\n end if;\n if p_action='join' and a.join_mode='approval' and (select count(*) from activities_private.members where activity_id=p_id and status='pending')>=100 then raise exception 'Liste de demandes complète'; end if;\n insert into activities_private.members(activity_id,user_id,status) values(p_id,target,case when p_action='decline' then 'declined' when p_action='join' and a.join_mode='approval' then 'pending' else 'accepted' end)\n on conflict(activity_id,user_id) do update set status=excluded.status,updated_at=clock_timestamp();\n insert into activities_private.notices(user_id,activity_id,kind) values(case when p_action='join' then a.organizer_id else target end,p_id,p_action) on conflict do nothing;\nend $function$\n"},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","args":"p_id uuid, p_action text, p_user uuid, p_reason text","name":"safety","owner":"postgres","schema":"activities_private","definition":"CREATE OR REPLACE FUNCTION activities_private.safety(p_id uuid, p_action text, p_user uuid, p_reason text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare me uuid:=auth.uid();a activities_private.activities%rowtype;\nbegin\n if not activities_private.allowed() then raise exception 'Accès non autorisé'; end if;\n -- Block locks every affected activity in UUID order before checking membership.\n if p_action='block' then\n  perform id from activities_private.activities where organizer_id in (me,p_user) order by id for update;\n end if;\n select * into a from activities_private.activities where id=p_id for update;\n if not activities_private.visible(p_id) then raise exception 'Activité inaccessible'; end if;\n if p_action='report' then\n  if length(trim(coalesce(p_reason,''))) not between 10 and 1000 then raise exception 'Motif requis : 10 à 1 000 caractères'; end if;\n  if (select count(*) from public.admin_reports where reporter_id=me and created_at>now()-interval '1 hour')>=10 then raise exception 'Trop de signalements récents'; end if;\n  if p_user is not null and not exists(select 1 from activities_private.members where activity_id=p_id and user_id=p_user and status='accepted') then raise exception 'Participant introuvable'; end if;\n  insert into public.admin_reports(reporter_id,target_kind,target_id,reason) values(me,case when p_user is null then 'activity' else 'user' end,coalesce(p_user,p_id),trim(p_reason)) on conflict do nothing;\n elsif p_action='block' then\n  if p_user is null or p_user=me or not exists(select 1 from activities_private.members where activity_id=p_id and user_id=p_user and status='accepted') then raise exception 'Participant invalide'; end if;\n  insert into activities_private.blocks(user_id,blocked_id) values(me,p_user) on conflict do nothing;\n  update activities_private.members m set status='left',updated_at=clock_timestamp() from activities_private.activities x where x.id=m.activity_id and ((x.organizer_id=p_user and m.user_id=me) or (x.organizer_id=me and m.user_id=p_user));\n else raise exception 'Action inconnue'; end if;\nend $function$\n"},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","args":"p_id uuid, p_data jsonb","name":"save","owner":"postgres","schema":"activities_private","definition":"CREATE OR REPLACE FUNCTION activities_private.save(p_id uuid, p_data jsonb)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare me uuid:=auth.uid(); id uuid:=coalesce(p_id,gen_random_uuid()); n integer; a activities_private.activities%rowtype;\nbegin\n if not activities_private.allowed() then raise exception 'Accès adulte non autorisé'; end if;\n -- Serialises creations per organiser, so the daily limit cannot race.\n perform pg_advisory_xact_lock(hashtextextended('activity-create:'||me::text,0));\n if p_id is null then\n  select count(*) into n from activities_private.activities where organizer_id=me and created_at>now()-interval '1 day';\n  if n>=5 then raise exception 'Limite de 5 créations par jour atteinte'; end if;\n else\n  select * into a from activities_private.activities where activities.id=p_id for update;\n  if not found or a.organizer_id<>me or a.status<>'open' then raise exception 'Modification non autorisée'; end if;\n  select count(*) into n from activities_private.members where activity_id=p_id and status='accepted';\n  if (p_data->>'capacity')::integer<n then raise exception 'Capacité inférieure au nombre de participants'; end if;\n end if;\n if (p_data->>'starts_at')::timestamptz<=now() then raise exception 'Date future requise'; end if;\n insert into activities_private.activities(id,organizer_id,title,description,category,starts_at,city,venue,capacity,visibility,join_mode,cost_mode,cost_amount,conditions)\n values(id,me,trim(p_data->>'title'),trim(p_data->>'description'),p_data->>'category',(p_data->>'starts_at')::timestamptz,trim(p_data->>'city'),coalesce(p_data->>'venue',''),(p_data->>'capacity')::integer,p_data->>'visibility',p_data->>'join_mode',p_data->>'cost_mode',case when p_data->>'cost_mode'='on_site' then (p_data->>'cost_amount')::numeric else null end,coalesce(p_data->>'conditions',''))\n on conflict on constraint activities_pkey do update set title=excluded.title,description=excluded.description,category=excluded.category,starts_at=excluded.starts_at,city=excluded.city,venue=excluded.venue,capacity=excluded.capacity,visibility=excluded.visibility,join_mode=excluded.join_mode,cost_mode=excluded.cost_mode,cost_amount=excluded.cost_amount,conditions=excluded.conditions,updated_at=clock_timestamp();\n insert into activities_private.locations(activity_id,address,latitude,longitude) values(id,coalesce(p_data->>'address',''),(p_data->>'latitude')::double precision,(p_data->>'longitude')::double precision)\n on conflict(activity_id) do update set address=excluded.address,latitude=excluded.latitude,longitude=excluded.longitude;\n if p_id is null then insert into activities_private.members values(id,me,'accepted',now());\n else insert into activities_private.notices(user_id,activity_id,kind) select user_id,id,'updated' from activities_private.members where activity_id=id and user_id<>me and status in ('accepted','pending') on conflict do nothing;\n end if;\n return id;\nend $function$\n"},{"acl":"{postgres=X/postgres}","args":"p_id uuid","name":"visible","owner":"postgres","schema":"activities_private","definition":"CREATE OR REPLACE FUNCTION activities_private.visible(p_id uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\n select activities_private.allowed() and exists(select 1 from activities_private.activities a where a.id=p_id and a.status<>'deleted' and not activities_private.blocked(a.organizer_id,auth.uid()) and (a.organizer_id=auth.uid() or (a.status<>'hidden' and (a.visibility='public' or public.are_friends(a.organizer_id,auth.uid()) or exists(select 1 from activities_private.members m where m.activity_id=a.id and m.user_id=auth.uid() and m.status='accepted')))))\n$function$\n"},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","args":"","name":"activities_capabilities","owner":"postgres","schema":"public","definition":"CREATE OR REPLACE FUNCTION public.activities_capabilities()\n RETURNS jsonb\n LANGUAGE sql\n SET search_path TO ''\nAS $function$select activities_private.capabilities()$function$\n"},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","args":"p_id uuid","name":"activities_detail","owner":"postgres","schema":"public","definition":"CREATE OR REPLACE FUNCTION public.activities_detail(p_id uuid)\n RETURNS jsonb\n LANGUAGE sql\n SET search_path TO ''\nAS $function$select activities_private.detail(p_id)$function$\n"},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","args":"","name":"activities_list","owner":"postgres","schema":"public","definition":"CREATE OR REPLACE FUNCTION public.activities_list()\n RETURNS jsonb\n LANGUAGE sql\n SET search_path TO ''\nAS $function$select activities_private.list()$function$\n"},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","args":"p_id uuid, p_action text, p_user uuid","name":"activities_participate","owner":"postgres","schema":"public","definition":"CREATE OR REPLACE FUNCTION public.activities_participate(p_id uuid, p_action text, p_user uuid DEFAULT NULL::uuid)\n RETURNS void\n LANGUAGE sql\n SET search_path TO ''\nAS $function$select activities_private.participate(p_id,p_action,p_user)$function$\n"},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","args":"p_id uuid, p_action text, p_user uuid, p_reason text","name":"activities_safety","owner":"postgres","schema":"public","definition":"CREATE OR REPLACE FUNCTION public.activities_safety(p_id uuid, p_action text, p_user uuid, p_reason text)\n RETURNS void\n LANGUAGE sql\n SET search_path TO ''\nAS $function$select activities_private.safety(p_id,p_action,p_user,p_reason)$function$\n"},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","args":"p_id uuid, p_data jsonb","name":"activities_save","owner":"postgres","schema":"public","definition":"CREATE OR REPLACE FUNCTION public.activities_save(p_id uuid, p_data jsonb)\n RETURNS uuid\n LANGUAGE sql\n SET search_path TO ''\nAS $function$select activities_private.save(p_id,p_data)$function$\n"}],"relations":[{"acl":"{postgres=arwdDxtm/postgres}","rls":true,"kind":"r","name":"activities","owner":"postgres","options":null,"force_rls":false,"persistence":"p","replica_identity":"d"},{"acl":"{postgres=arwdDxtm/postgres}","rls":false,"kind":"i","name":"activities_discovery","owner":"postgres","options":null,"force_rls":false,"persistence":"p","replica_identity":"n"},{"acl":"{postgres=arwdDxtm/postgres}","rls":false,"kind":"i","name":"activities_owner","owner":"postgres","options":null,"force_rls":false,"persistence":"p","replica_identity":"n"},{"acl":"{postgres=arwdDxtm/postgres}","rls":false,"kind":"i","name":"activities_pkey","owner":"postgres","options":null,"force_rls":false,"persistence":"p","replica_identity":"n"},{"acl":"{postgres=arwdDxtm/postgres}","rls":false,"kind":"i","name":"activity_member_user","owner":"postgres","options":null,"force_rls":false,"persistence":"p","replica_identity":"n"},{"acl":"{postgres=arwdDxtm/postgres}","rls":true,"kind":"r","name":"adult_access","owner":"postgres","options":null,"force_rls":false,"persistence":"p","replica_identity":"d"},{"acl":"{postgres=arwdDxtm/postgres}","rls":false,"kind":"i","name":"adult_access_pkey","owner":"postgres","options":null,"force_rls":false,"persistence":"p","replica_identity":"n"},{"acl":"{postgres=arwdDxtm/postgres}","rls":true,"kind":"r","name":"blocks","owner":"postgres","options":null,"force_rls":false,"persistence":"p","replica_identity":"d"},{"acl":"{postgres=arwdDxtm/postgres}","rls":false,"kind":"i","name":"blocks_pkey","owner":"postgres","options":null,"force_rls":false,"persistence":"p","replica_identity":"n"},{"acl":"{postgres=arwdDxtm/postgres}","rls":true,"kind":"r","name":"locations","owner":"postgres","options":null,"force_rls":false,"persistence":"p","replica_identity":"d"},{"acl":"{postgres=arwdDxtm/postgres}","rls":false,"kind":"i","name":"locations_pkey","owner":"postgres","options":null,"force_rls":false,"persistence":"p","replica_identity":"n"},{"acl":"{postgres=arwdDxtm/postgres}","rls":true,"kind":"r","name":"members","owner":"postgres","options":null,"force_rls":false,"persistence":"p","replica_identity":"d"},{"acl":"{postgres=arwdDxtm/postgres}","rls":false,"kind":"i","name":"members_pkey","owner":"postgres","options":null,"force_rls":false,"persistence":"p","replica_identity":"n"},{"acl":"{postgres=arwdDxtm/postgres}","rls":true,"kind":"r","name":"notices","owner":"postgres","options":null,"force_rls":false,"persistence":"p","replica_identity":"d"},{"acl":"{postgres=rwU/postgres}","rls":false,"kind":"S","name":"notices_id_seq","owner":"postgres","options":null,"force_rls":false,"persistence":"p","replica_identity":"n"},{"acl":"{postgres=arwdDxtm/postgres}","rls":false,"kind":"i","name":"notices_pkey","owner":"postgres","options":null,"force_rls":false,"persistence":"p","replica_identity":"n"},{"acl":"{postgres=arwdDxtm/postgres}","rls":false,"kind":"i","name":"notices_user_id_activity_id_kind_version_key","owner":"postgres","options":null,"force_rls":false,"persistence":"p","replica_identity":"n"},{"acl":"{postgres=arwdDxtm/postgres}","rls":true,"kind":"r","name":"settings","owner":"postgres","options":null,"force_rls":false,"persistence":"p","replica_identity":"d"},{"acl":"{postgres=arwdDxtm/postgres}","rls":false,"kind":"i","name":"settings_pkey","owner":"postgres","options":null,"force_rls":false,"persistence":"p","replica_identity":"n"}],"sequences":[{"max":"9223372036854775807","min":"1","name":"notices_id_seq","type":"bigint","cache":"1","cycle":false,"start":"1","increment":"1"}],"constraints":[{"name":"activities_capacity_check","type":"c","table":"activities","deferred":false,"noinherit":false,"validated":true,"deferrable":false,"definition":"CHECK (((capacity >= 2) AND (capacity <= 100)))"},{"name":"activities_category_check","type":"c","table":"activities","deferred":false,"noinherit":false,"validated":true,"deferrable":false,"definition":"CHECK ((category = ANY (ARRAY['restaurant'::text, 'randonnee'::text, 'cinema'::text, 'bowling'::text, 'sport'::text, 'jeux'::text, 'culture'::text, 'famille'::text, 'autres'::text])))"},{"name":"activities_check","type":"c","table":"activities","deferred":false,"noinherit":false,"validated":true,"deferrable":false,"definition":"CHECK ((((cost_mode = 'free'::text) AND (cost_amount IS NULL)) OR ((cost_mode = 'on_site'::text) AND (cost_amount IS NOT NULL) AND (cost_amount > (0)::numeric) AND (cost_amount <= (10000)::numeric))))"},{"name":"activities_city_check","type":"c","table":"activities","deferred":false,"noinherit":false,"validated":true,"deferrable":false,"definition":"CHECK (((length(TRIM(BOTH FROM city)) >= 1) AND (length(TRIM(BOTH FROM city)) <= 100)))"},{"name":"activities_conditions_check","type":"c","table":"activities","deferred":false,"noinherit":false,"validated":true,"deferrable":false,"definition":"CHECK ((length(conditions) <= 2000))"},{"name":"activities_cost_mode_check","type":"c","table":"activities","deferred":false,"noinherit":false,"validated":true,"deferrable":false,"definition":"CHECK ((cost_mode = ANY (ARRAY['free'::text, 'on_site'::text])))"},{"name":"activities_description_check","type":"c","table":"activities","deferred":false,"noinherit":false,"validated":true,"deferrable":false,"definition":"CHECK (((length(TRIM(BOTH FROM description)) >= 1) AND (length(TRIM(BOTH FROM description)) <= 4000)))"},{"name":"activities_join_mode_check","type":"c","table":"activities","deferred":false,"noinherit":false,"validated":true,"deferrable":false,"definition":"CHECK ((join_mode = ANY (ARRAY['direct'::text, 'approval'::text])))"},{"name":"activities_organizer_id_fkey","type":"f","table":"activities","deferred":false,"noinherit":true,"validated":true,"deferrable":false,"definition":"FOREIGN KEY (organizer_id) REFERENCES auth.users(id)"},{"name":"activities_pkey","type":"p","table":"activities","deferred":false,"noinherit":true,"validated":true,"deferrable":false,"definition":"PRIMARY KEY (id)"},{"name":"activities_status_check","type":"c","table":"activities","deferred":false,"noinherit":false,"validated":true,"deferrable":false,"definition":"CHECK ((status = ANY (ARRAY['open'::text, 'cancelled'::text, 'deleted'::text, 'hidden'::text])))"},{"name":"activities_title_check","type":"c","table":"activities","deferred":false,"noinherit":false,"validated":true,"deferrable":false,"definition":"CHECK (((length(TRIM(BOTH FROM title)) >= 1) AND (length(TRIM(BOTH FROM title)) <= 120)))"},{"name":"activities_venue_check","type":"c","table":"activities","deferred":false,"noinherit":false,"validated":true,"deferrable":false,"definition":"CHECK ((length(venue) <= 200))"},{"name":"activities_visibility_check","type":"c","table":"activities","deferred":false,"noinherit":false,"validated":true,"deferrable":false,"definition":"CHECK ((visibility = ANY (ARRAY['public'::text, 'friends'::text])))"},{"name":"adult_access_approved_by_fkey","type":"f","table":"adult_access","deferred":false,"noinherit":true,"validated":true,"deferrable":false,"definition":"FOREIGN KEY (approved_by) REFERENCES auth.users(id)"},{"name":"adult_access_pkey","type":"p","table":"adult_access","deferred":false,"noinherit":true,"validated":true,"deferrable":false,"definition":"PRIMARY KEY (user_id)"},{"name":"adult_access_user_id_fkey","type":"f","table":"adult_access","deferred":false,"noinherit":true,"validated":true,"deferrable":false,"definition":"FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE"},{"name":"blocks_blocked_id_fkey","type":"f","table":"blocks","deferred":false,"noinherit":true,"validated":true,"deferrable":false,"definition":"FOREIGN KEY (blocked_id) REFERENCES auth.users(id) ON DELETE CASCADE"},{"name":"blocks_check","type":"c","table":"blocks","deferred":false,"noinherit":false,"validated":true,"deferrable":false,"definition":"CHECK ((user_id <> blocked_id))"},{"name":"blocks_pkey","type":"p","table":"blocks","deferred":false,"noinherit":true,"validated":true,"deferrable":false,"definition":"PRIMARY KEY (user_id, blocked_id)"},{"name":"blocks_user_id_fkey","type":"f","table":"blocks","deferred":false,"noinherit":true,"validated":true,"deferrable":false,"definition":"FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE"},{"name":"locations_activity_id_fkey","type":"f","table":"locations","deferred":false,"noinherit":true,"validated":true,"deferrable":false,"definition":"FOREIGN KEY (activity_id) REFERENCES activities_private.activities(id) ON DELETE CASCADE"},{"name":"locations_address_check","type":"c","table":"locations","deferred":false,"noinherit":false,"validated":true,"deferrable":false,"definition":"CHECK ((length(address) <= 300))"},{"name":"locations_check","type":"c","table":"locations","deferred":false,"noinherit":false,"validated":true,"deferrable":false,"definition":"CHECK ((((latitude IS NULL) AND (longitude IS NULL)) OR ((latitude IS NOT NULL) AND (longitude IS NOT NULL) AND ((latitude >= ('-90'::integer)::double precision) AND (latitude <= (90)::double precision)) AND ((longitude >= ('-180'::integer)::double precision) AND (longitude <= (180)::double precision)))))"},{"name":"locations_pkey","type":"p","table":"locations","deferred":false,"noinherit":true,"validated":true,"deferrable":false,"definition":"PRIMARY KEY (activity_id)"},{"name":"members_activity_id_fkey","type":"f","table":"members","deferred":false,"noinherit":true,"validated":true,"deferrable":false,"definition":"FOREIGN KEY (activity_id) REFERENCES activities_private.activities(id) ON DELETE CASCADE"},{"name":"members_pkey","type":"p","table":"members","deferred":false,"noinherit":true,"validated":true,"deferrable":false,"definition":"PRIMARY KEY (activity_id, user_id)"},{"name":"members_status_check","type":"c","table":"members","deferred":false,"noinherit":false,"validated":true,"deferrable":false,"definition":"CHECK ((status = ANY (ARRAY['accepted'::text, 'pending'::text, 'declined'::text, 'left'::text])))"},{"name":"members_user_id_fkey","type":"f","table":"members","deferred":false,"noinherit":true,"validated":true,"deferrable":false,"definition":"FOREIGN KEY (user_id) REFERENCES auth.users(id)"},{"name":"notices_activity_id_fkey","type":"f","table":"notices","deferred":false,"noinherit":true,"validated":true,"deferrable":false,"definition":"FOREIGN KEY (activity_id) REFERENCES activities_private.activities(id)"},{"name":"notices_pkey","type":"p","table":"notices","deferred":false,"noinherit":true,"validated":true,"deferrable":false,"definition":"PRIMARY KEY (id)"},{"name":"notices_user_id_activity_id_kind_version_key","type":"u","table":"notices","deferred":false,"noinherit":true,"validated":true,"deferrable":false,"definition":"UNIQUE (user_id, activity_id, kind, version)"},{"name":"notices_user_id_fkey","type":"f","table":"notices","deferred":false,"noinherit":true,"validated":true,"deferrable":false,"definition":"FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE"},{"name":"settings_id_check","type":"c","table":"settings","deferred":false,"noinherit":false,"validated":true,"deferrable":false,"definition":"CHECK (id)"},{"name":"settings_pkey","type":"p","table":"settings","deferred":false,"noinherit":true,"validated":true,"deferrable":false,"definition":"PRIMARY KEY (id)"}],"extra_types":[]}$expected$::jsonb;
 actual jsonb; constraint_def text; constraint_valid boolean; before_public text; after_public text; before_reports text; after_reports text; bad_key text;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('orevami-activities-v1-install',0));
 IF current_user<>'postgres' THEN RAISE EXCEPTION 'Installation role mismatch'; END IF;
 IF to_regprocedure('auth.uid()') IS NULL OR to_regprocedure('public.are_friends(uuid,uuid)') IS NULL OR to_regprocedure('public.myevent_account_active()') IS NULL THEN RAISE EXCEPTION 'Missing existing dependencies'; END IF;
 SELECT pg_get_constraintdef(oid),convalidated INTO constraint_def,constraint_valid FROM pg_constraint WHERE conrelid='public.admin_reports'::regclass AND conname='admin_reports_target_kind_check' AND contype='c';
 IF NOT coalesce(constraint_valid,false) OR constraint_def NOT IN ($initial$CHECK ((target_kind = ANY (ARRAY['event'::text, 'listing'::text])))$initial$,$final$CHECK ((target_kind = ANY (ARRAY['event'::text, 'listing'::text, 'activity'::text, 'user'::text])))$final$) THEN RAISE EXCEPTION 'Report constraint divergence'; END IF;
 select jsonb_build_object(
 'schema',(select jsonb_build_object('owner',pg_get_userbyid(nspowner),'acl',coalesce(nspacl,acldefault('n',nspowner))::text) from pg_namespace where nspname='activities_private'),
 'relations',(select coalesce(jsonb_agg(jsonb_build_object('name',c.relname,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'options',c.reloptions,'persistence',c.relpersistence,'replica_identity',c.relreplident,'acl',coalesce(c.relacl,acldefault(case when c.relkind='S' then 'S'::"char" else 'r'::"char" end,c.relowner))::text) order by c.relname),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='activities_private'),
 'columns',(select coalesce(jsonb_agg(jsonb_build_object('table',c.relname,'number',a.attnum,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'dropped',a.attisdropped,'default',pg_get_expr(d.adbin,d.adrelid),'collation',a.attcollation::regcollation::text,'acl',a.attacl::text) order by c.relname,a.attnum),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid and a.attnum>0 left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum where n.nspname='activities_private'),
 'constraints',(select coalesce(jsonb_agg(jsonb_build_object('table',c.relname,'name',k.conname,'type',k.contype,'definition',pg_get_constraintdef(k.oid),'validated',k.convalidated,'deferrable',k.condeferrable,'deferred',k.condeferred,'noinherit',k.connoinherit) order by c.relname,k.conname),'[]') from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='activities_private'),
 'indexes',(select coalesce(jsonb_agg(jsonb_build_object('name',c.relname,'definition',pg_get_indexdef(c.oid),'valid',i.indisvalid,'ready',i.indisready) order by c.relname),'[]') from pg_index i join pg_class c on c.oid=i.indexrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='activities_private'),
 'sequences',(select coalesce(jsonb_agg(jsonb_build_object('name',c.relname,'type',s.seqtypid::regtype::text,'start',s.seqstart::text,'increment',s.seqincrement::text,'min',s.seqmin::text,'max',s.seqmax::text,'cache',s.seqcache::text,'cycle',s.seqcycle) order by c.relname),'[]') from pg_sequence s join pg_class c on c.oid=s.seqrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='activities_private'),
 'policies',(select coalesce(jsonb_agg(jsonb_build_object('table',c.relname,'name',p.polname,'command',p.polcmd,'permissive',p.polpermissive,'roles',p.polroles::text,'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid)) order by c.relname,p.polname),'[]') from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='activities_private'),
 'triggers',(select coalesce(jsonb_agg(jsonb_build_object('table',c.relname,'name',t.tgname,'definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled) order by c.relname,t.tgname),'[]') from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='activities_private' and not t.tgisinternal),
 'functions',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'definition',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),'acl',coalesce(p.proacl,acldefault('f',p.proowner))::text) order by n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)),'[]') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='activities_private' or (n.nspname='public' and left(p.proname,11)='activities_')),
 'extra_types',(select coalesce(jsonb_agg(t.typname order by t.typname),'[]') from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname='activities_private' and t.typrelid=0 and t.typelem=0)
) INTO actual;
 IF actual->'schema'<>'null'::jsonb OR jsonb_array_length(actual->'functions')>0 THEN
  IF actual IS DISTINCT FROM expected THEN
   SELECT key INTO bad_key FROM jsonb_each(expected) e WHERE actual->e.key IS DISTINCT FROM e.value ORDER BY key LIMIT 1;
   RAISE EXCEPTION 'Existing foundation divergence: %',bad_key;
  END IF;
  IF constraint_def<>$final$CHECK ((target_kind = ANY (ARRAY['event'::text, 'listing'::text, 'activity'::text, 'user'::text])))$final$ THEN RAISE EXCEPTION 'Incomplete report extension'; END IF;
  RAISE NOTICE 'Conforming foundation: no changes'; RETURN;
 END IF;
 -- No catalog/data write has occurred above this point.
 LOCK TABLE public.admin_reports IN SHARE ROW EXCLUSIVE MODE;
 IF EXISTS(select 1 from public.admin_reports where target_kind not in ('event','listing','activity','user')) THEN RAISE EXCEPTION 'Incompatible report data'; END IF;
 select md5(coalesce(string_agg(x.line,E'\n' order by x.line),'')) from (
 select jsonb_build_array('relation',c.relname,c.relkind,c.relrowsecurity,c.relforcerowsecurity,c.relacl::text,c.reloptions,pg_get_userbyid(c.relowner))::text line from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'
 union all select jsonb_build_array('column',c.relname,a.attnum,a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attacl::text,pg_get_expr(d.adbin,d.adrelid))::text from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid and a.attnum>0 left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum where n.nspname='public'
 union all select jsonb_build_array('constraint',c.relname,k.conname,pg_get_constraintdef(k.oid),k.convalidated)::text from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and not(c.relname='admin_reports' and k.conname='admin_reports_target_kind_check')
 union all select jsonb_build_array('policy',c.relname,p.polname,p.polcmd,p.polpermissive,p.polroles::text,pg_get_expr(p.polqual,p.polrelid),pg_get_expr(p.polwithcheck,p.polrelid))::text from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'
 union all select jsonb_build_array('function',p.oid::regprocedure::text,pg_get_functiondef(p.oid),p.proacl::text,pg_get_userbyid(p.proowner))::text from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and left(p.proname,11)<>'activities_' and p.prokind in ('f','p')
) x INTO before_public;
 SELECT md5(coalesce(string_agg(to_jsonb(r)::text,E'\n' order by id),'')) INTO before_reports FROM public.admin_reports r;
 EXECUTE $install$create schema activities_private;
revoke all on schema activities_private from public,anon,authenticated;
grant usage on schema activities_private to authenticated;
create table activities_private.settings(id boolean primary key default true check(id),enabled boolean not null default false);
insert into activities_private.settings values(true,false);
-- Administrative eligibility decision; never populated from editable user_metadata.
-- No UI grants itself eligibility. TEST fixtures may be approved explicitly by an administrator.
create table activities_private.adult_access(user_id uuid primary key references auth.users(id) on delete cascade,approved_by uuid not null references auth.users(id),approved_at timestamptz not null default now(),revoked_at timestamptz);
create table activities_private.activities(
 id uuid primary key default gen_random_uuid(),organizer_id uuid not null references auth.users(id),
 title text not null check(length(trim(title)) between 1 and 120),description text not null check(length(trim(description)) between 1 and 4000),
 category text not null check(category in ('restaurant','randonnee','cinema','bowling','sport','jeux','culture','famille','autres')),
 starts_at timestamptz not null,city text not null check(length(trim(city)) between 1 and 100),venue text not null default '' check(length(venue)<=200),
 capacity integer not null check(capacity between 2 and 100),visibility text not null check(visibility in ('public','friends')),
 join_mode text not null check(join_mode in ('direct','approval')),cost_mode text not null check(cost_mode in ('free','on_site')),
 cost_amount numeric(8,2),conditions text not null default '' check(length(conditions)<=2000),
 status text not null default 'open' check(status in ('open','cancelled','deleted','hidden')),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 check((cost_mode='free' and cost_amount is null) or (cost_mode='on_site' and cost_amount is not null and cost_amount>0 and cost_amount<=10000))
);
create index activities_discovery on activities_private.activities(status,starts_at);
create index activities_owner on activities_private.activities(organizer_id,created_at);
create table activities_private.locations(
 activity_id uuid primary key references activities_private.activities(id) on delete cascade,
 address text not null default '' check(length(address)<=300),latitude double precision,longitude double precision,
 check((latitude is null and longitude is null) or (latitude is not null and longitude is not null and latitude between -90 and 90 and longitude between -180 and 180))
);
create table activities_private.members(
 activity_id uuid not null references activities_private.activities(id) on delete cascade,user_id uuid not null references auth.users(id),
 status text not null check(status in ('accepted','pending','declined','left')),updated_at timestamptz not null default now(),primary key(activity_id,user_id)
);
create index activity_member_user on activities_private.members(user_id,status);
create table activities_private.blocks(user_id uuid not null references auth.users(id) on delete cascade,blocked_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,blocked_id),check(user_id<>blocked_id));
-- Single recipient/event/version uniqueness prevents duplicate notices on retry.
-- A future inbox adapter must consume these rows, rather than generate notices again.
create table activities_private.notices(id bigint generated always as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,activity_id uuid not null references activities_private.activities(id),kind text not null,version timestamptz not null default now(),created_at timestamptz not null default now(),unique(user_id,activity_id,kind,version));
-- No direct table access, including from PostgREST; RLS default-deny is defense in depth.
do $$declare t text;begin
 foreach t in array array['settings','adult_access','activities','locations','members','blocks','notices'] loop
  execute format('alter table activities_private.%I enable row level security',t);
  execute format('revoke all on activities_private.%I from public,anon,authenticated',t);
 end loop;
end $$;
revoke all on all sequences in schema activities_private from public,anon,authenticated;
create function activities_private.allowed() returns boolean language sql stable security definer set search_path='' as $$
 select auth.uid() is not null and public.myevent_account_active() and exists(select 1 from activities_private.settings where enabled) and exists(select 1 from activities_private.adult_access where user_id=auth.uid() and revoked_at is null)
$$;
create function activities_private.blocked(a uuid,b uuid) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from activities_private.blocks where (user_id=a and blocked_id=b) or (user_id=b and blocked_id=a))
$$;
create function activities_private.visible(p_id uuid) returns boolean language sql stable security definer set search_path='' as $$
 select activities_private.allowed() and exists(select 1 from activities_private.activities a where a.id=p_id and a.status<>'deleted' and not activities_private.blocked(a.organizer_id,auth.uid()) and (a.organizer_id=auth.uid() or (a.status<>'hidden' and (a.visibility='public' or public.are_friends(a.organizer_id,auth.uid()) or exists(select 1 from activities_private.members m where m.activity_id=a.id and m.user_id=auth.uid() and m.status='accepted')))))
$$;
create function activities_private.capabilities() returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('enabled',coalesce((select enabled from activities_private.settings),false),'adult_access',auth.uid() is not null and public.myevent_account_active() and exists(select 1 from activities_private.adult_access where user_id=auth.uid() and revoked_at is null),'version',1)
$$;
create function activities_private.detail(p_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare a activities_private.activities%rowtype; me uuid:=auth.uid(); accepted boolean; owner boolean; result jsonb;
begin
 if not activities_private.visible(p_id) then return null; end if;
 select * into a from activities_private.activities where id=p_id;
 owner:=a.organizer_id=me;
 accepted:=owner or exists(select 1 from activities_private.members where activity_id=p_id and user_id=me and status='accepted');
 select to_jsonb(a)-'created_at'-'updated_at' || jsonb_build_object(
  'is_owner',owner,'membership',(select status from activities_private.members where activity_id=p_id and user_id=me),
  'participants_count',(select count(*) from activities_private.members where activity_id=p_id and status='accepted'),
  'remaining',greatest(0,a.capacity-(select count(*) from activities_private.members where activity_id=p_id and status='accepted')),
  'address',case when accepted then l.address else null end,
  'position',case when l.latitude is null then null else jsonb_build_object('lat',round(l.latitude::numeric,2),'lon',round(l.longitude::numeric,2)) end,
  'members',case when accepted then coalesce((select jsonb_agg(jsonb_build_object('user_id',m.user_id,'status',m.status,'display_name',coalesce(p.display_name,'Participant'))) from activities_private.members m left join public.profiles p on p.id=m.user_id where m.activity_id=p_id and (m.status='accepted' or (owner and m.status='pending')) and not activities_private.blocked(me,m.user_id)),'[]'::jsonb) else '[]'::jsonb end)
 into result from activities_private.locations l where l.activity_id=p_id;
 return result;
end $$;
create function activities_private.list() returns jsonb language sql stable security definer set search_path='' as $$
 select coalesce(jsonb_agg(x.detail order by x.starts_at),'[]'::jsonb) from (
 select a.starts_at,activities_private.detail(a.id)-'members'-'address'-'description'-'conditions' as detail
 from activities_private.activities a where activities_private.visible(a.id) and (a.starts_at>now() or a.organizer_id=auth.uid() or exists(select 1 from activities_private.members m where m.activity_id=a.id and m.user_id=auth.uid() and m.status in ('accepted','pending'))) order by a.starts_at limit 300) x
$$;
create function activities_private.save(p_id uuid,p_data jsonb) returns uuid language plpgsql security definer set search_path='' as $$
declare me uuid:=auth.uid(); id uuid:=coalesce(p_id,gen_random_uuid()); n integer; a activities_private.activities%rowtype;
begin
 if not activities_private.allowed() then raise exception 'Accès adulte non autorisé'; end if;
 -- Serialises creations per organiser, so the daily limit cannot race.
 perform pg_advisory_xact_lock(hashtextextended('activity-create:'||me::text,0));
 if p_id is null then
  select count(*) into n from activities_private.activities where organizer_id=me and created_at>now()-interval '1 day';
  if n>=5 then raise exception 'Limite de 5 créations par jour atteinte'; end if;
 else
  select * into a from activities_private.activities where activities.id=p_id for update;
  if not found or a.organizer_id<>me or a.status<>'open' then raise exception 'Modification non autorisée'; end if;
  select count(*) into n from activities_private.members where activity_id=p_id and status='accepted';
  if (p_data->>'capacity')::integer<n then raise exception 'Capacité inférieure au nombre de participants'; end if;
 end if;
 if (p_data->>'starts_at')::timestamptz<=now() then raise exception 'Date future requise'; end if;
 insert into activities_private.activities(id,organizer_id,title,description,category,starts_at,city,venue,capacity,visibility,join_mode,cost_mode,cost_amount,conditions)
 values(id,me,trim(p_data->>'title'),trim(p_data->>'description'),p_data->>'category',(p_data->>'starts_at')::timestamptz,trim(p_data->>'city'),coalesce(p_data->>'venue',''),(p_data->>'capacity')::integer,p_data->>'visibility',p_data->>'join_mode',p_data->>'cost_mode',case when p_data->>'cost_mode'='on_site' then (p_data->>'cost_amount')::numeric else null end,coalesce(p_data->>'conditions',''))
 on conflict on constraint activities_pkey do update set title=excluded.title,description=excluded.description,category=excluded.category,starts_at=excluded.starts_at,city=excluded.city,venue=excluded.venue,capacity=excluded.capacity,visibility=excluded.visibility,join_mode=excluded.join_mode,cost_mode=excluded.cost_mode,cost_amount=excluded.cost_amount,conditions=excluded.conditions,updated_at=clock_timestamp();
 insert into activities_private.locations(activity_id,address,latitude,longitude) values(id,coalesce(p_data->>'address',''),(p_data->>'latitude')::double precision,(p_data->>'longitude')::double precision)
 on conflict(activity_id) do update set address=excluded.address,latitude=excluded.latitude,longitude=excluded.longitude;
 if p_id is null then insert into activities_private.members values(id,me,'accepted',now());
 else insert into activities_private.notices(user_id,activity_id,kind) select user_id,id,'updated' from activities_private.members where activity_id=id and user_id<>me and status in ('accepted','pending') on conflict do nothing;
 end if;
 return id;
end $$;
create function activities_private.participate(p_id uuid,p_action text,p_user uuid default null) returns void language plpgsql security definer set search_path='' as $$
declare me uuid:=auth.uid();a activities_private.activities%rowtype;target uuid:=coalesce(p_user,auth.uid());previous text;n integer;
begin
 if not activities_private.allowed() then raise exception 'Accès adulte non autorisé'; end if;
 -- Every seat mutation and capacity edit uses this exact activity row lock.
 select * into a from activities_private.activities where id=p_id for update;
 if not found then raise exception 'Activité introuvable'; end if;
 if p_action='leave' then
  if target<>me or a.organizer_id=me then raise exception 'Annulez votre activité en tant qu’organisateur'; end if;
  update activities_private.members set status='left',updated_at=clock_timestamp() where activity_id=p_id and user_id=me and status in ('accepted','pending');
  if found then insert into activities_private.notices(user_id,activity_id,kind) values(a.organizer_id,p_id,'left') on conflict do nothing; end if;
  return;
 end if;
 if not activities_private.visible(p_id) then raise exception 'Activité inaccessible'; end if;
 if p_action in ('cancel','delete') then
  if a.organizer_id<>me then raise exception 'Réservé à l’organisateur'; end if;
  if a.status='deleted' or (a.status='cancelled' and p_action='cancel') then return; end if;
  update activities_private.activities set status=case when p_action='cancel' then 'cancelled' else 'deleted' end,updated_at=clock_timestamp() where id=p_id;
  update activities_private.locations set address='',latitude=null,longitude=null where activity_id=p_id;
  insert into activities_private.notices(user_id,activity_id,kind) select user_id,p_id,p_action from activities_private.members where activity_id=p_id and user_id<>me and status in ('accepted','pending') on conflict do nothing;
  return;
 end if;
 if a.status<>'open' or a.starts_at<=now() then raise exception 'Inscriptions fermées'; end if;
 select status into previous from activities_private.members where activity_id=p_id and user_id=target;
 if p_action='join' then
  if target<>me then raise exception 'Inscription pour soi uniquement'; end if;
  if previous in ('accepted','pending') then return; end if;
  if previous='declined' then raise exception 'Demande refusée par l’organisateur'; end if;
  if (select count(*) from activities_private.members where user_id=me and updated_at>now()-interval '1 hour')>=20 then raise exception 'Trop de demandes récentes'; end if;
 elsif p_action in ('accept','decline') then
  if a.organizer_id<>me or target=me or previous is distinct from 'pending' then raise exception 'Demande non modifiable'; end if;
  if activities_private.blocked(me,target) then raise exception 'Utilisateur bloqué'; end if;
  if not exists(select 1 from activities_private.adult_access where user_id=target and revoked_at is null) then raise exception 'Accès adulte révoqué'; end if;
 else raise exception 'Action inconnue'; end if;
 if p_action='accept' or (p_action='join' and a.join_mode='direct') then
  select count(*) into n from activities_private.members where activity_id=p_id and status='accepted';
  if n>=a.capacity then raise exception 'Activité complète'; end if;
 end if;
 if p_action='join' and a.join_mode='approval' and (select count(*) from activities_private.members where activity_id=p_id and status='pending')>=100 then raise exception 'Liste de demandes complète'; end if;
 insert into activities_private.members(activity_id,user_id,status) values(p_id,target,case when p_action='decline' then 'declined' when p_action='join' and a.join_mode='approval' then 'pending' else 'accepted' end)
 on conflict(activity_id,user_id) do update set status=excluded.status,updated_at=clock_timestamp();
 insert into activities_private.notices(user_id,activity_id,kind) values(case when p_action='join' then a.organizer_id else target end,p_id,p_action) on conflict do nothing;
end $$;
-- Existing moderation queue is reused; no second reports queue.
alter table public.admin_reports drop constraint admin_reports_target_kind_check;
alter table public.admin_reports add constraint admin_reports_target_kind_check check(target_kind in ('event','listing','activity','user'));
create function activities_private.safety(p_id uuid,p_action text,p_user uuid,p_reason text) returns void language plpgsql security definer set search_path='' as $$
declare me uuid:=auth.uid();a activities_private.activities%rowtype;
begin
 if not activities_private.allowed() then raise exception 'Accès non autorisé'; end if;
 -- Block locks every affected activity in UUID order before checking membership.
 if p_action='block' then
  perform id from activities_private.activities where organizer_id in (me,p_user) order by id for update;
 end if;
 select * into a from activities_private.activities where id=p_id for update;
 if not activities_private.visible(p_id) then raise exception 'Activité inaccessible'; end if;
 if p_action='report' then
  if length(trim(coalesce(p_reason,''))) not between 10 and 1000 then raise exception 'Motif requis : 10 à 1 000 caractères'; end if;
  if (select count(*) from public.admin_reports where reporter_id=me and created_at>now()-interval '1 hour')>=10 then raise exception 'Trop de signalements récents'; end if;
  if p_user is not null and not exists(select 1 from activities_private.members where activity_id=p_id and user_id=p_user and status='accepted') then raise exception 'Participant introuvable'; end if;
  insert into public.admin_reports(reporter_id,target_kind,target_id,reason) values(me,case when p_user is null then 'activity' else 'user' end,coalesce(p_user,p_id),trim(p_reason)) on conflict do nothing;
 elsif p_action='block' then
  if p_user is null or p_user=me or not exists(select 1 from activities_private.members where activity_id=p_id and user_id=p_user and status='accepted') then raise exception 'Participant invalide'; end if;
  insert into activities_private.blocks(user_id,blocked_id) values(me,p_user) on conflict do nothing;
  update activities_private.members m set status='left',updated_at=clock_timestamp() from activities_private.activities x where x.id=m.activity_id and ((x.organizer_id=p_user and m.user_id=me) or (x.organizer_id=me and m.user_id=p_user));
 else raise exception 'Action inconnue'; end if;
end $$;
-- Public wrappers are SECURITY INVOKER, the narrow definer operations live in a non-exposed schema.
create function public.activities_capabilities() returns jsonb language sql security invoker set search_path='' as $$select activities_private.capabilities()$$;
create function public.activities_list() returns jsonb language sql security invoker set search_path='' as $$select activities_private.list()$$;
create function public.activities_detail(p_id uuid) returns jsonb language sql security invoker set search_path='' as $$select activities_private.detail(p_id)$$;
create function public.activities_save(p_id uuid,p_data jsonb) returns uuid language sql security invoker set search_path='' as $$select activities_private.save(p_id,p_data)$$;
create function public.activities_participate(p_id uuid,p_action text,p_user uuid default null) returns void language sql security invoker set search_path='' as $$select activities_private.participate(p_id,p_action,p_user)$$;
create function public.activities_safety(p_id uuid,p_action text,p_user uuid,p_reason text) returns void language sql security invoker set search_path='' as $$select activities_private.safety(p_id,p_action,p_user,p_reason)$$;
revoke all on all functions in schema activities_private from public,anon,authenticated;
grant execute on function activities_private.capabilities(),activities_private.list(),activities_private.detail(uuid),activities_private.save(uuid,jsonb),activities_private.participate(uuid,text,uuid),activities_private.safety(uuid,text,uuid,text) to authenticated;
revoke all on function public.activities_capabilities(),public.activities_list(),public.activities_detail(uuid),public.activities_save(uuid,jsonb),public.activities_participate(uuid,text,uuid),public.activities_safety(uuid,text,uuid,text) from public,anon,authenticated,service_role;
grant execute on function public.activities_capabilities(),public.activities_list(),public.activities_detail(uuid),public.activities_save(uuid,jsonb),public.activities_participate(uuid,text,uuid),public.activities_safety(uuid,text,uuid,text) to authenticated;
$install$;
 select jsonb_build_object(
 'schema',(select jsonb_build_object('owner',pg_get_userbyid(nspowner),'acl',coalesce(nspacl,acldefault('n',nspowner))::text) from pg_namespace where nspname='activities_private'),
 'relations',(select coalesce(jsonb_agg(jsonb_build_object('name',c.relname,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'options',c.reloptions,'persistence',c.relpersistence,'replica_identity',c.relreplident,'acl',coalesce(c.relacl,acldefault(case when c.relkind='S' then 'S'::"char" else 'r'::"char" end,c.relowner))::text) order by c.relname),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='activities_private'),
 'columns',(select coalesce(jsonb_agg(jsonb_build_object('table',c.relname,'number',a.attnum,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'dropped',a.attisdropped,'default',pg_get_expr(d.adbin,d.adrelid),'collation',a.attcollation::regcollation::text,'acl',a.attacl::text) order by c.relname,a.attnum),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid and a.attnum>0 left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum where n.nspname='activities_private'),
 'constraints',(select coalesce(jsonb_agg(jsonb_build_object('table',c.relname,'name',k.conname,'type',k.contype,'definition',pg_get_constraintdef(k.oid),'validated',k.convalidated,'deferrable',k.condeferrable,'deferred',k.condeferred,'noinherit',k.connoinherit) order by c.relname,k.conname),'[]') from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='activities_private'),
 'indexes',(select coalesce(jsonb_agg(jsonb_build_object('name',c.relname,'definition',pg_get_indexdef(c.oid),'valid',i.indisvalid,'ready',i.indisready) order by c.relname),'[]') from pg_index i join pg_class c on c.oid=i.indexrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='activities_private'),
 'sequences',(select coalesce(jsonb_agg(jsonb_build_object('name',c.relname,'type',s.seqtypid::regtype::text,'start',s.seqstart::text,'increment',s.seqincrement::text,'min',s.seqmin::text,'max',s.seqmax::text,'cache',s.seqcache::text,'cycle',s.seqcycle) order by c.relname),'[]') from pg_sequence s join pg_class c on c.oid=s.seqrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='activities_private'),
 'policies',(select coalesce(jsonb_agg(jsonb_build_object('table',c.relname,'name',p.polname,'command',p.polcmd,'permissive',p.polpermissive,'roles',p.polroles::text,'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid)) order by c.relname,p.polname),'[]') from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='activities_private'),
 'triggers',(select coalesce(jsonb_agg(jsonb_build_object('table',c.relname,'name',t.tgname,'definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled) order by c.relname,t.tgname),'[]') from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='activities_private' and not t.tgisinternal),
 'functions',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'definition',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),'acl',coalesce(p.proacl,acldefault('f',p.proowner))::text) order by n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)),'[]') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='activities_private' or (n.nspname='public' and left(p.proname,11)='activities_')),
 'extra_types',(select coalesce(jsonb_agg(t.typname order by t.typname),'[]') from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname='activities_private' and t.typrelid=0 and t.typelem=0)
) INTO actual;
 IF actual IS DISTINCT FROM expected THEN
  SELECT key INTO bad_key FROM jsonb_each(expected) e WHERE actual->e.key IS DISTINCT FROM e.value ORDER BY key LIMIT 1;
  RAISE EXCEPTION 'Installed foundation divergence: %',bad_key;
 END IF;
 select md5(coalesce(string_agg(x.line,E'\n' order by x.line),'')) from (
 select jsonb_build_array('relation',c.relname,c.relkind,c.relrowsecurity,c.relforcerowsecurity,c.relacl::text,c.reloptions,pg_get_userbyid(c.relowner))::text line from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'
 union all select jsonb_build_array('column',c.relname,a.attnum,a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attacl::text,pg_get_expr(d.adbin,d.adrelid))::text from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid and a.attnum>0 left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum where n.nspname='public'
 union all select jsonb_build_array('constraint',c.relname,k.conname,pg_get_constraintdef(k.oid),k.convalidated)::text from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and not(c.relname='admin_reports' and k.conname='admin_reports_target_kind_check')
 union all select jsonb_build_array('policy',c.relname,p.polname,p.polcmd,p.polpermissive,p.polroles::text,pg_get_expr(p.polqual,p.polrelid),pg_get_expr(p.polwithcheck,p.polrelid))::text from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'
 union all select jsonb_build_array('function',p.oid::regprocedure::text,pg_get_functiondef(p.oid),p.proacl::text,pg_get_userbyid(p.proowner))::text from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and left(p.proname,11)<>'activities_' and p.prokind in ('f','p')
) x INTO after_public;
 SELECT md5(coalesce(string_agg(to_jsonb(r)::text,E'\n' order by id),'')) INTO after_reports FROM public.admin_reports r;
 IF before_public IS DISTINCT FROM after_public OR before_reports IS DISTINCT FROM after_reports THEN RAISE EXCEPTION 'Existing objects or report data changed unexpectedly'; END IF;
 IF (SELECT enabled FROM activities_private.settings WHERE id) IS DISTINCT FROM false OR EXISTS(SELECT 1 FROM activities_private.adult_access) THEN RAISE EXCEPTION 'Activation must remain closed'; END IF;
 RAISE NOTICE 'Foundation installed; activation closed; existing objects and reports preserved';
END $guard$;

